/**
 * AD Sync Config API Lambda
 *
 * GET  /adsyncconfig  — Return tenant's AD sync config + hasCredentials boolean
 * PUT  /adsyncconfig  — Save config to DynamoDB + credentials to Secrets Manager
 * POST /adsyncconfig  — Action dispatch: trigger sync or test connection
 */

import { DynamoDBClient, GetItemCommand, PutItemCommand } from '@aws-sdk/client-dynamodb';
import {
  SecretsManagerClient, GetSecretValueCommand,
  UpdateSecretCommand, CreateSecretCommand,
} from '@aws-sdk/client-secrets-manager';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';
import { validateTenantAccess, getTenantIdFromRequest, createResponse, createLogger } from 'admin-auth';

const logger = createLogger('adsyncconfig');
const dynamodb = new DynamoDBClient({});
const secrets = new SecretsManagerClient({});
const lambda = new LambdaClient({});

export const handler = async (event) => {
  console.log(JSON.stringify({ level: "DEBUG", event: "ADSYNCCONFIG_INVOKED", method: event.requestContext?.http?.method, timestamp: new Date().toISOString() }));

  try {
    const tenantId = getTenantIdFromRequest(event);
    if (!tenantId) {
      return createResponse(400, { error: 'tenant_id required in request' });
    }

    const authResult = await validateTenantAccess(event, tenantId);
    if (!authResult.authorized) {
      return createResponse(authResult.statusCode, { error: authResult.error });
    }

    const method = event.requestContext?.http?.method;
    console.log(JSON.stringify({ level: "DEBUG", event: "REQUEST", tenantId, method }));

    switch (method) {
      case 'GET':
        return await handleGet(tenantId);
      case 'PUT':
        return await handlePut(tenantId, event);
      case 'POST':
        return await handlePost(tenantId, event);
      case 'OPTIONS':
        return createResponse(200, { data: 'ok' });
      default:
        return createResponse(405, { error: `Method ${method} not allowed` });
    }
  } catch (err) {
    console.error(JSON.stringify({ level: "ERROR", event: "HANDLER_ERROR", error: err.message, stack: err.stack }));
    return createResponse(500, { error: 'Internal server error' });
  }
};

const LDAP_FIELD_NAME_RE = /^[a-zA-Z][a-zA-Z0-9\-;]*$/;

function validateFieldMappings(fieldMappings) {
  const invalid = [];
  for (const [cognitoField, mapping] of Object.entries(fieldMappings)) {
    const adField = mapping?.adField;
    if (adField && !LDAP_FIELD_NAME_RE.test(adField)) {
      invalid.push(`${cognitoField}→"${adField}"`);
    }
  }
  return invalid;
}

async function handleGet(tenantId) {
  console.log(JSON.stringify({ level: "DEBUG", event: "GET_CONFIG", tenantId }));

  const item = await dynamodb.send(new GetItemCommand({
    TableName: process.env.CONFIG_TABLE,
    Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
  }));

  const config = item.Item?.value?.S ? JSON.parse(item.Item.value.S) : null;

  let hasCredentials = false;
  try {
    await secrets.send(new GetSecretValueCommand({ SecretId: `apersona/${tenantId}/ad-sync` }));
    hasCredentials = true;
  } catch (e) {
    if (e.name !== 'ResourceNotFoundException') {
      console.error(JSON.stringify({ level: "ERROR", event: "SECRET_CHECK_ERROR", tenantId, error: e.message }));
    }
  }

  console.log(JSON.stringify({ level: "DEBUG", event: "GET_CONFIG_RESULT", tenantId, hasConfig: !!config, hasCredentials }));
  return createResponse(200, { data: { ...config, hasCredentials } });
}

async function handlePut(tenantId, event) {
  const body = JSON.parse(event.body);
  const { credentials, ...configData } = body.data;

  // Validate custom AD field names in fieldMappings to prevent LDAP injection
  if (configData.fieldMappings) {
    const invalid = validateFieldMappings(configData.fieldMappings);
    if (invalid.length > 0) {
      console.error(JSON.stringify({ level: "ERROR", event: "INVALID_FIELD_NAMES", tenantId, invalid }));
      return createResponse(400, { error: `Invalid AD field names: ${invalid.join(', ')}. Field names must be alphanumeric with hyphens and semicolons only.` });
    }
  }

  console.log(JSON.stringify({
    level: "DEBUG", event: "PUT_CONFIG", tenantId,
    enabled: configData.enabled, ldapProvider: configData.ldapProvider,
    hasCredentials: !!(credentials?.bindPassword),
  }));

  // Save non-sensitive config to DynamoDB
  await dynamodb.send(new PutItemCommand({
    TableName: process.env.CONFIG_TABLE,
    Item: {
      id: { S: tenantId },
      configtype: { S: 'adSyncConfig' },
      value: { S: JSON.stringify(configData) },
    },
  }));

  console.log(JSON.stringify({ level: "INFO", event: "CONFIG_SAVED", tenantId }));

  // Save credentials to Secrets Manager (if provided)
  if (credentials?.bindPassword) {
    const secretValue = JSON.stringify({
      bindDN: credentials.bindDN || configData.ldapBindDN,
      bindPassword: credentials.bindPassword,
      updatedAt: new Date().toISOString(),
    });

    try {
      await secrets.send(new UpdateSecretCommand({
        SecretId: `apersona/${tenantId}/ad-sync`,
        SecretString: secretValue,
      }));
      console.log(JSON.stringify({ level: "INFO", event: "CREDENTIALS_UPDATED", tenantId }));
    } catch (e) {
      if (e.name === 'ResourceNotFoundException') {
        await secrets.send(new CreateSecretCommand({
          Name: `apersona/${tenantId}/ad-sync`,
          SecretString: secretValue,
        }));
        console.log(JSON.stringify({ level: "INFO", event: "CREDENTIALS_CREATED", tenantId }));
      } else {
        throw e;
      }
    }
  }

  return createResponse(200, { data: configData });
}

async function handlePost(tenantId, event) {
  const body = JSON.parse(event.body);
  const action = body.action;

  console.log(JSON.stringify({ level: "DEBUG", event: "POST_ACTION", tenantId, action }));

  switch (action) {
    case 'sync': {
      await lambda.send(new InvokeCommand({
        FunctionName: process.env.SYNC_WORKER_FUNCTION_NAME,
        InvocationType: 'Event',
        Payload: JSON.stringify({ tenantId }),
      }));
      console.log(JSON.stringify({ level: "INFO", event: "SYNC_TRIGGERED", tenantId }));
      return createResponse(202, { data: { message: 'Sync triggered', tenantId } });
    }
    case 'test-connection': {
      const abortController = new AbortController();
      const timeout = setTimeout(() => abortController.abort(), 25_000);
      try {
        const result = await lambda.send(new InvokeCommand({
          FunctionName: process.env.SYNC_WORKER_FUNCTION_NAME,
          InvocationType: 'RequestResponse',
          Payload: JSON.stringify({ tenantId, action: 'test-connection' }),
        }), { abortSignal: abortController.signal });
        clearTimeout(timeout);
        const payload = JSON.parse(new TextDecoder().decode(result.Payload));
        console.log(JSON.stringify({ level: "INFO", event: "CONNECTION_TEST_RESULT", tenantId, payload }));
        return createResponse(200, { data: payload });
      } catch (err) {
        clearTimeout(timeout);
        if (err.name === 'AbortError') {
          console.error(JSON.stringify({ level: "ERROR", event: "CONNECTION_TEST_TIMEOUT", tenantId }));
          return createResponse(200, { data: { success: false, error: 'Connection test timed out (25s). Check LDAP URL and network connectivity.' } });
        }
        throw err;
      }
    }
    default:
      return createResponse(400, { error: `Unknown action: ${action}` });
  }
}
